SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);tt:=Cputime();R:=PolynomialRing(Integers());fp:=FrobeniusPolynomial(JH(72,[37]),5);assert Degree(fp) eq 82;tr:=[];closed:=[];
for n in [1..10] do z:=-n*Coefficient(fp,82-n);for j in [1..n-1] do z-:=Coefficient(fp,82-j)*tr[n-j];end for;Append(~tr,Integers()!z);num:=5^n+1-z;for k in Divisors(n) do if k lt n then num-:=k*closed[k];end if;end for;assert num mod n eq 0;Append(~closed,Integers()!(num div n));end for;
nc:=[closed[d]-(d eq 1 select 24 else d eq 2 select 8 else d eq 6 select 4 else 0):d in [1..10]];assert nc[1..9] eq [0,0,48,120,720,2904,10416,50334,218080];Write("work/deg10/C236_resolution_20261030/enumeration/frobenius.m",Sprint([*Coefficients(fp),[1:i in [1..24]] cat [2:i in [1..8]] cat [6:i in [1..4]],nc*]):Overwrite:=true);
rows:=[* *];count:=[0:i in Divisors(10)];keys:={};pol:=[];js:=[];curves:=0;fours:=0;nines:=0;
