assert #Seqset(js) eq 1 and js[1] eq (5^10+5^5+4*5^2+4*5) div 10;assert count eq [nc[d]:d in Divisors(10)];Write("work/deg10/C236_resolution_20261030/enumeration/source10.m",Sprint([*10,pol,true,js[1],curves,fours,nines,count,rows*]):Overwrite:=true);print "C236_SOURCE10_MERGE_COMPLETE",count,#rows,nc,Cputime(tt);quit;
